        Set-ADAccountPassword -Identity $randomuser -Reset -NewPassword (ConvertTo-SecureString $password -AsPlainText -Force)
        Set-ADUser $randomuser -Description "New user generated password: $password"
        Write-Info "Password in Description : $randomuser $password"
        $Global:InitialAccessUsers += $randomuser;
    }
}
function VulnAD-PasswordSpraying {
    $same_password = ($Global:Domain -replace "\.\w+", "")+([string](VulnAD-RandInt -Max 100)).PadLeft(3, '0')
    $count = 2 + (VulnAD-RandInt -Max 4)
    for ($i=1; $i -le $count; $i=$i+1 ) {
        $randomuser = VulnAD-PickFreshUser -Pool (VulnAD-NormalPool)
        if (-not $randomuser) { break }
        Set-ADAccountPassword -Identity $randomuser -Reset -NewPassword (ConvertTo-SecureString $same_password -AsPlainText -Force)
        Set-ADUser $randomuser -Description "Company default password (reset ASAP)"
        Write-Info "Same Password (Password Spraying) : $randomuser $same_password"
        $Global:InitialAccessUsers += $randomuser;
    }
}
function Counter{
    param(
        [string]$path
    )
    $counter = @{};
    foreach ($letter in [char[]]$path){
        $letter = [string]$letter
        if (-not $counter.Contains($letter)){
            $counter[$letter] =  0
        }
        $counter[$letter] += 1
    }
    return $counter
}
function getList{
    param(
        [string]$path,
        [array]$list
    )
    $r = 0
    $newlist = [System.Collections.ArrayList]::new()
    foreach ($o in $list)
    {
        $newlist.add($o)
        
    }
    $mapping = @("Marketing", "Sales", "Accounting", "Senior management", "Project management", "IT Helpdesk", "Office Admin", "IT Admins", "Executives")
    foreach ($i in (Counter($path)).keys){
        if ((Counter($path))[$i] -ge 2){
            foreach ($j in (Counter($path)).keys){
                $newlist.remove($mapping[$j-1])
            }
        }
    }
    return $newlist
}
function getPath{
    $mapping = @{"Marketing" = "1"; "Sales" = "2"; "Accounting" = "3"; "Senior management" = "4"; "Project management" = "5"; "IT Helpdesk" = "6"; "Office Admin" = "7"; "IT admins" = "8"; "Executives" = "9";}
    $path = ""
    $path2 = ""
    $end = VulnAD-GetRandom -InputList $Global:HighGroups
    $middle = VulnAD-GetRandom -InputList $Global:MidGroups
    $start = VulnAD-GetRandom -InputList $Global:NormalGroups
    $path += $mapping[$start]
    $path2 += $mapping[$middle]
    if ((VulnAD-RandInt -Max 2)){
        while ($path[-1] -ne $mapping[$end]){
            $path += $mapping[(VulnAD-GetRandom -InputList (getList -path $path -list ($Global:NormalGroups+$end)))]
        }
        Write-Info "Path: $path"
        return $path
    }
    else{
        while ($path[-1] -ne $mapping[$middle]){
            $path += $mapping[(VulnAD-GetRandom -InputList (getList -path $path -list ($Global:NormalGroups+$middle)))]
        }
        while ($path2[-1] -ne $mapping[$end]){
            $path2 += $mapping[(VulnAD-GetRandom -InputList (getList -path ($path+$path2) -list ($Global:MidGroups+$end)))]
        }
        Write-Info "Path: $path$path2"
        return $path+$path2
    }
}
function VulnAD-NewChainUser {
    # Creates a uniquely-named user for the ACL attack chain and returns its SamAccountName.
    # Without the uniqueness check a name collision would silently skip creation and the
    # chain would re-use an existing employee instead.
    $firstname = (VulnAD-GetRandom -InputList $Global:HumansNames);
    $lastname  = (VulnAD-GetRandom -InputList $Global:HumansNames);
    $generated_password = (VulnAD-GenPassword -len 7)
    $base = ("{0}.{1}" -f $firstname, $lastname).ToLower();
    $sam = $base; $suffix = 2;
    while (($Global:CreatedUsers -contains $sam) -or ($Global:ExtraUsers -contains $sam)) { $sam = "$base$suffix"; $suffix++ }
    $display = ("$firstname $lastname " + $sam.Substring($base.Length)).Trim()
    Try {
        New-ADUser -Name $display -GivenName $firstname -Surname $lastname -SamAccountName $sam -UserPrincipalName "$sam@$Global:Domain" -AccountPassword (ConvertTo-SecureString $generated_password -AsPlainText -Force) -PassThru | Enable-ADAccount
    } Catch { Write-Bad "Chain user $sam could not be created: $($_.Exception.Message)" }
    $Global:ExtraUsers += $sam
    return $sam
}

function VulnAD-UserAcl{
    param(
        [string]$src,
        [string]$dst
    )
    $mapping = @("","Marketing", "Sales", "Accounting", "Senior management", "Project management", "IT Helpdesk", "Office Admin", "It Admins", "Executives")
    $SamAccountName = VulnAD-NewChainUser
    Try { Add-ADGroupMember -Identity $mapping[$dst] -Members $SamAccountName } Catch {}
    if ($Global:ACLUser){
        $SrcUser = Get-ADUser -identity $Global:ACLUser
    }
    else {
        $SrcUser = Get-ADUser -identity (VulnAD-GetRandom -InputList $Global:InitialAccessUsers)
        # Compare on SamAccountName: "-ne <ADUser object>" never matches the string list.
        $Global:InitialAccessUsers = @($Global:InitialAccessUsers | Where-Object { $_ -ne $SrcUser.SamAccountName })
    }
    $DstUser = Get-ADUser -identity $SamAccountName
    $Global:ACLUser = $DstUser
    VulnAD-AddACL -Source $SrcUser.sid -Destination $DstUser.DistinguishedName -Rights "GenericAll"
    Write-Info ("Giving "+$SrcUser.SamAccountName+" GenericAll over "+$DstUser.SamAccountName+" ("+$mapping[$dst]+")")
}
function VulnAD-GroupUserAcl{
    param(
        [string]$src,
        [string]$dst
    )
    $mapping = @("","Marketing", "Sales", "Accounting", "Senior management", "Project management", "IT Helpdesk", "Office Admin", "It Admins", "Executives")

    $SamAccountName = VulnAD-NewChainUser
