}
function VulnAD-BadAcls {
    $mapping = @($Global:Marketing, $Global:Sales, $Global:Accounting, $Global:Seniormanagement, $Global:Projectmanagement, $Global:ITHelpdesk, $Global:OfficeAdmin, $Global:ITAdmins, $Global:Executives)
    $path = getPath
    if ($path[0] -eq $path[1]){
        $DstUser = Get-ADUser -identity (VulnAD-GetRandom -InputList ($mapping[[string]$path[1]-1]))
        $InitialUser = Get-ADUser -identity (VulnAD-GetRandom -InputList $Global:InitialAccessUsers)
        # Compare on SamAccountName: "-ne <ADUser object>" never matches the string list.
        $Global:InitialAccessUsers = @($Global:InitialAccessUsers | Where-Object { $_ -ne $InitialUser.SamAccountName })
        $Global:ACLUser = $DstUser
        VulnAD-AddACL -Source $InitialUser.sid -Destination $DstUser.DistinguishedName -Rights "GenericAll"
        Write-Info ("Giving "+$InitialUser.SamAccountName+" GenericAll over "+$DstUser.SamAccountName)
    }
    $count = 0
    $Duplicates = @()
    foreach ($i in (Counter($path)).keys){
        if ((Counter($path))[$i] -ge 2){
            $Duplicates += $i
        }
    }
    $DupPosition = @()
    $DupPosition2 = @()
    foreach ($i in $Duplicates){
        $DupPosition += [string]$path.LastIndexOf($i)
    }
    foreach ($i in $Duplicates){
        $DupPosition2 += [string]($path.LastIndexOf($i)+2)
    }
    $intersect = $DupPosition | ?{$DupPosition2 -contains $_}
    foreach ($num in [char[]]$path[1..(([char[]]$path).Count-1)]){
        $count++
        if([string]$path[[string]$count-1] -eq [string]$path[$count] -or $intersect -eq $count+1){
            VulnAD-UserAcl -src ([string]$path[[string]$count-1]) -dst ([string]$path[$count])
        }
        elseif ($DupPosition.Contains([string]$count)){
            VulnAD-GroupUserAcl -src ([string]$path[[string]$count-1]) -dst ([string]$path[$count])
        }
        elseif ($DupPosition2.Contains([string]($count+1))){
            VulnAD-UserGroupAcl -dst ([string]$path[$count])
        }
        else{
            VulnAD-GroupAcl -src ([string]$path[[string]$count-1]) -dst ([string]$path[$count])
        }

    }
    $mapping = @("Marketing", "Sales", "Accounting", "Senior management", "Project management", "IT Helpdesk", "Office Admin", "It Admins", "Executives")
    VulnAD-DCSync -group ($mapping[([string]$path[-1]-1)])

    foreach ($abuse in $Global:ACLperm) {
        $hgroup = VulnAD-GetRandom -InputList $Global:HighGroups
        $mgroup = VulnAD-GetRandom -InputList $Global:MidGroups
        $DstGroup = Get-ADGroup -Identity $hgroup
        $SrcGroup = Get-ADGroup -Identity $mgroup
        VulnAD-AddACL -Source $SrcGroup.sid -Destination $DstGroup.DistinguishedName -Rights $abuse
        Write-Info "BadACL $hgroup has $abuse permission for $mgroup"
    }
    $noise1 = 10 + (VulnAD-RandInt -Max 20)
    for ($i=1; $i -le $noise1; $i=$i+1 ) {
        $abuse = (VulnAD-GetRandom -InputList $Global:ACLperm);
        $randomuser = VulnAD-GetRandom -InputList $Global:CreatedUsers
        $randomgroup = VulnAD-GetRandom -InputList $Global:AllObjects
        if ((VulnAD-RandInt -Max 2)){
            $Dstobj = Get-ADUser -Identity $randomuser
            $Srcobj = Get-ADGroup -Identity $randomgroup
        }else{
            $Srcobj = Get-ADUser -Identity $randomuser
            $Dstobj = Get-ADGroup -Identity $randomgroup
        }
        VulnAD-AddACL -Source $Srcobj.sid -Destination $Dstobj.DistinguishedName -Rights $abuse 
        Write-Info "BadACL $randomgroup has $abuse permission for $randomuser"
    }
    $noise2 = 1 + (VulnAD-RandInt -Max 29)
    for ($i=1; $i -le $noise2; $i=$i+1 ) {
        $abuse = (VulnAD-GetRandom -InputList $Global:ACLperm);
        $randomuser = VulnAD-GetRandom -InputList $Global:CreatedUsers
        $randomuser2 = VulnAD-GetRandom -InputList $Global:CreatedUsers
        If(-not($randomuser -eq $randomuser2)){
        $Dstobj = Get-ADUser -Identity $randomuser
        $Srcobj = Get-ADUser -Identity $randomuser2
        VulnAD-AddACL -Source $Srcobj.sid -Destination $Dstobj.DistinguishedName -Rights $abuse 
        Write-Info "BadACL $randomuser has $abuse permission for $randomuser2"
        }
    }
}
function VulnAD-DCSync {
    param(
        [string]$group
    )
    $Identity  = (Get-ADGroup -Identity $group)
    $nb = (Get-ADDomain).NetBIOSName
    $acct = "$nb\$($Identity.Name)"
    $RootDSE = [ADSI]"LDAP://RootDSE"
    $DefaultNamingContext = $RootDse.defaultNamingContext
    $ConfigurationNamingContext = $RootDse.configurationNamingContext

    DSACLS "$DefaultNamingContext" /G "$($acct):CA;Replicating Directory Changes" | Out-Null
    DSACLS "$ConfigurationNamingContext" /G "$($acct):CA;Replicating Directory Changes" | Out-Null

    DSACLS "$DefaultNamingContext" /G "$($acct):CA;Replicating Directory Changes All" | Out-Null
    DSACLS "$ConfigurationNamingContext" /G "$($acct):CA;Replicating Directory Changes All" | Out-Null

    DSACLS "$DefaultNamingContext" /G "$($acct):CA;Replicating Directory Changes In Filtered Set" | Out-Null
    DSACLS "$ConfigurationNamingContext" /G "$($acct):CA;Replicating Directory Changes In Filtered Set" | Out-Null
    Write-Info "DCSync granted -> $acct ($group)"
}
function VulnAD-RBCD {
    # Dusuk yetkili bir kullaniciya, sahte bir servis/computer nesnesi uzerinde
    # GenericWrite hakki vererek RBCD (Resource-Based Constrained Delegation) zafiyeti olusturur.
    # Saldirgan: kendi sahte computer hesabini olusturur (MachineAccountQuota),
    # msDS-AllowedToActOnBehalfOfOtherIdentity'yi bu hesaba yazar, S4U2Self/S4U2Proxy ile bilet alir.
    Add-Type -AssemblyName System.Web
    $svcName = "FILESRV"
    $svcPassword = (VulnAD-GenPassword -len 12)
    Try {
        New-ADComputer -Name $svcName -SAMAccountName "$svcName`$" -AccountPassword (ConvertTo-SecureString $svcPassword -AsPlainText -Force) -Enabled $true -ServicePrincipalNames "CIFS/$svcName.$Global:Domain","HOST/$svcName.$Global:Domain"
        Write-Info "RBCD: fake service account created -> $svcName`$"
    } Catch { Write-Bad "RBCD: could not create account $svcName`$" }

    Try {
        $lowPrivUser = VulnAD-GetRandom -InputList $Global:ITHelpdesk
        $lowUserObj = Get-ADUser -Identity $lowPrivUser
        $targetComputer = Get-ADComputer -Identity $svcName
        VulnAD-AddACL -Source $lowUserObj.sid -Destination $targetComputer.DistinguishedName -Rights "GenericWrite"
        Write-Info "RBCD: $lowPrivUser has GenericWrite over $svcName`$ (RBCD abuse possible)"
    } Catch { Write-Bad "RBCD: ACL could not be granted" }
}
function VulnAD-ADCS {
    # AD CS (Enterprise CA + Web Enrollment) kurar ve ESC1/ESC4 zafiyetli template'ler olusturur.
    Write-Info "Installing AD CS roles (Certification Authority + Web Enrollment)"
    Try {
        Install-WindowsFeature ADCS-Cert-Authority,ADCS-Web-Enrollment -IncludeManagementTools | Out-Null
        Install-AdcsCertificationAuthority -CAType EnterpriseRootCA -CACommonName "$($Global:Domain)-CA" -KeyLength 2048 -HashAlgorithmName SHA256 -Force | Out-Null
        Install-AdcsWebEnrollment -Force | Out-Null
        Write-Info "AD CS installed. Web Enrollment is exposed over HTTP (ESC8 relay target)"
    } Catch { Write-Bad "AD CS installation may have failed (it may already be installed)" }

    $NewTemplateName = "ESC1Template"
    Try {
        $ConfigContext = (Get-ADRootDSE).configurationNamingContext
        $TemplatePath = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$ConfigContext"
        $SourceTemplate = "CN=User,$TemplatePath"
        $NewTemplateDN = "CN=$NewTemplateName,$TemplatePath"

        $Source = [ADSI]"LDAP://$SourceTemplate"
        $Parent = [ADSI]"LDAP://$TemplatePath"
        $New = $Parent.Create("pKICertificateTemplate","CN=$NewTemplateName")
        # Copy the User template's attributes EXCEPT its OID (a duplicate OID breaks enrollment).
        foreach ($attr in @('pKIDefaultKeySpec','pKIMaxIssuingDepth','pKICriticalExtensions','pKIExpirationPeriod','pKIOverlapPeriod','pKIDefaultCSPs','pKIKeyUsage','msPKI-RA-Signature','msPKI-Enrollment-Flag','msPKI-Private-Key-Flag','msPKI-Minimal-Key-Size','msPKI-Template-Schema-Version','msPKI-Template-Minor-Revision','msPKI-Certificate-Application-Policy','pKIExtendedKeyUsage','revision','flags')) {
            Try { $New.Put($attr, $Source.psbase.InvokeGet($attr)) } Catch {}
        }
        # Give this template its OWN unique OID (derived from the User template's base OID).
        Try {
            $srcOid = [string]$Source.psbase.InvokeGet('msPKI-Cert-Template-OID')
            $New.Put('msPKI-Cert-Template-OID', "$srcOid.4718")
        } Catch {}
        $New.Put("displayName", $NewTemplateName)
        # ENROLLEE_SUPPLIES_SUBJECT bit = 0x1 -> ESC1
        $New.Put("msPKI-Certificate-Name-Flag", 1)
        # No manager approval, no RA signatures needed.
        $New.Put("msPKI-Enrollment-Flag", 0)
        $New.Put("msPKI-RA-Signature", 0)
        $New.SetInfo()

        # Domain Users'a Enroll hakki ver
        $TemplateObj = [ADSI]"LDAP://$NewTemplateDN"
        $DomainUsers = New-Object System.Security.Principal.NTAccount("Domain Users")
        $SID = $DomainUsers.Translate([System.Security.Principal.SecurityIdentifier])
        $EnrollGuid = [GUID]"0e10c968-78fb-11d2-90d4-00c04f79dc55"
        $adRights = [System.DirectoryServices.ActiveDirectoryRights]"ExtendedRight"
        $type = [System.Security.AccessControl.AccessControlType]"Allow"
        $ace = New-Object System.DirectoryServices.ActiveDirectoryAccessRule $SID,$adRights,$type,$EnrollGuid
        $TemplateObj.psbase.ObjectSecurity.AddAccessRule($ace)
        $TemplateObj.psbase.CommitChanges()

        Try { Restart-Service certsvc -ErrorAction SilentlyContinue; Start-Sleep -Seconds 10 } Catch {}
        certutil -SetCATemplates "+$NewTemplateName" | Out-Null
        Write-Info "ADCS ESC1: template $NewTemplateName created, Domain Users can enroll, SAN is attacker-specifiable"
    } Catch { Write-Bad "ESC1 template could not be created" }

    Try {
        $ConfigContext = (Get-ADRootDSE).configurationNamingContext
        $TemplatePath = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$ConfigContext"
        $NewTemplateDN = "CN=$NewTemplateName,$TemplatePath"
        $mgroup = VulnAD-GetRandom -InputList $Global:NormalGroups
        $SrcGroup = Get-ADGroup -Identity $mgroup
        VulnAD-AddACL -Source $SrcGroup.sid -Destination $NewTemplateDN -Rights "WriteDACL"
        Write-Info "ADCS ESC4: $mgroup granted WriteDACL over template $NewTemplateName (can convert it to ESC1)"
    } Catch { Write-Bad "ESC4 ACL could not be granted" }
}
function VulnAD-ShadowCredentials {
    # Dusuk yetkili kullaniciya, yuksek yetkili bir kullanicinin msDS-KeyCredentialLink
    # (Shadow Credentials / Whisker) attribute'unu yazma hakkini (GenericWrite) verir.
    Try {
        $lowUser = VulnAD-GetRandom -InputList $Global:ITHelpdesk
        $highUser = VulnAD-GetRandom -InputList $Global:ITAdmins
        $lowUserObj = Get-ADUser -Identity $lowUser
        $highUserObj = Get-ADUser -Identity $highUser
        VulnAD-AddACL -Source $lowUserObj.sid -Destination $highUserObj.DistinguishedName -Rights "GenericWrite"
        Write-Info "Shadow Credentials: $lowUser has GenericWrite (msDS-KeyCredentialLink) over $highUser"
    } Catch { Write-Bad "Shadow Credentials ACL could not be granted" }
}
function VulnAD-DisableSMBSigning {
        # Client yok, tek DC var: SMB CLIENT config'i degil SERVER config'i kapatmak lazim.
        # Boylece DC'nin kendi SMB servisine karsi relay/PtH gibi saldirilar anlamli hale gelir.
        Set-SmbServerConfiguration -RequireSecuritySignature 0 -EnableSecuritySignature 0 -Confirm:$false
}

