    # escalate (Sales -> Accounting -> management) to read everything. \\DC1\Common stays public.
    $base = "C:\Common"
    $nb = (Get-ADDomain).NetBIOSName

    # --- Extra accounting / finance documents ---
    $acc = "$base\Finance"
    New-Item -ItemType Directory -Path "$acc\Invoices" -Force | Out-Null
    Set-Content -Encoding UTF8 -Path "$acc\Invoices\INV-2024-1001.txt" -Value @"
