            New-Service -Name "VulnUpdateSvc" -BinaryPathName $binPath -DisplayName "Vuln Update Service" -StartupType Automatic | Out-Null
        }
        # Authenticated Users must be able to (a) write into the folder that ends before the space
        # and (b) restart the service, otherwise the vector cannot be triggered at all.
        icacls "$svcDir" /grant "*S-1-5-11:(OI)(CI)M" | Out-Null
        sc.exe sdset VulnUpdateSvc "D:(A;;CCLCSWRPWPDTLOCRRC;;;SY)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;BA)(A;;CCLCSWRPWPDTLOCRRC;;;AU)" | Out-Null
        Write-Info "Unquoted Service Path: VulnUpdateSvc -> $binPath (writable: $svcDir, Authenticated Users can start/stop)"
    } Catch { Write-Bad "Unquoted service path could not be created: $($_.Exception.Message)" }

    # --- AlwaysInstallElevated ---
    # HKCU alone would only cover the Administrator profile that runs this script, so the
    # Default user hive is patched too -> every profile created later (first WinRM logon) inherits it.
    Try {
        New-Item -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Installer" -Force | Out-Null
        New-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Installer" -Name "AlwaysInstallElevated" -PropertyType DWord -Value 1 -Force | Out-Null
        New-Item -Path "HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer" -Force | Out-Null
        New-ItemProperty -Path "HKCU:\SOFTWARE\Policies\Microsoft\Windows\Installer" -Name "AlwaysInstallElevated" -PropertyType DWord -Value 1 -Force | Out-Null
        reg.exe load "HKU\VulnADDefault" "C:\Users\Default\NTUSER.DAT" | Out-Null
        reg.exe add "HKU\VulnADDefault\SOFTWARE\Policies\Microsoft\Windows\Installer" /v AlwaysInstallElevated /t REG_DWORD /d 1 /f | Out-Null
        [gc]::Collect(); Start-Sleep -Seconds 2
        reg.exe unload "HKU\VulnADDefault" | Out-Null
        Write-Info "AlwaysInstallElevated = 1 (HKLM + HKCU + Default user profile)"
    } Catch { Write-Bad "AlwaysInstallElevated could not be set" }

    # --- Writable Scheduled Task (SYSTEM context, writable folder) ---
    # The folder MUST be writable by low-priv users or the vector does not work at all.
    # Repeats every 5 minutes instead of once at 03:00 so students do not have to wait.
    Try {
        $taskDir = "C:\Users\Public\Maintenance"
