        $scriptPath = "$taskDir\cleanup.bat"
        "@echo off`r`necho Running maintenance cleanup..." | Out-File -FilePath $scriptPath -Encoding ascii
        icacls "$taskDir" /grant "*S-1-5-11:(OI)(CI)M" /T | Out-Null      # Authenticated Users: Modify
