        Write-Info "Writable Scheduled Task: SystemMaintenanceCleanup -> $scriptPath (SYSTEM, every 5 min, Authenticated Users: Modify)"
    } Catch { Write-Bad "Scheduled task could not be created: $($_.Exception.Message)" }

    # --- Autologon plaintext credential in registry ---
    Try {
        $deployUser = "svc_deploy"
        $deployPassword = "Deploy2024!"
