            New-ADUser -Name $deployUser -SamAccountName $deployUser -UserPrincipalName "$deployUser@$Global:Domain" -AccountPassword (ConvertTo-SecureString $deployPassword -AsPlainText -Force) -PassThru | Enable-ADAccount
            Add-ADGroupMember -Identity "IT Helpdesk" -Members $deployUser -ErrorAction SilentlyContinue
        } Catch {}

