        New-Item -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" -Force | Out-Null
        New-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" -Name "NoAutoUpdate" -PropertyType DWord -Value 1 -Force | Out-Null
        Write-Info "Windows Update services stopped and disabled"
    } Catch { Write-Bad "Windows Update could not be disabled" }

    # --- Guc ayarlari: High Performance, uyku/hazirda bekletme kapali, sunucu asla kapanmasin ---
    Try {
        powercfg /setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c
