function VulnAD-CachedAdminCreds {
    # REAL-WORLD SCENARIO: a privileged service account runs a scheduled task on the server.
    # Without this there is nothing for Mimikatz / Empire / Havoc to steal from memory on a
    # client-less single-DC lab, and BloodHound shows no session data at all.
    #
    # Two independent payoffs for the student once they are SYSTEM on the DC:
    #   1. The task's stored password lands in LSA secrets -> lsadump::secrets / secretsdump
    #   2. WDigest UseLogonCredential=1 -> plaintext creds in LSASS -> sekurlsa::logonpasswords
    $svc  = "svc_backupadm"
    $pass = "Backup#Adm2024!"

    # WDigest: cache plaintext credentials in memory (off by default since 2012 R2).
    Try {
        Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest" -Name "UseLogonCredential" -Value 1 -Type DWord -Force
        Write-Info "WDigest UseLogonCredential=1 (plaintext credentials cached in LSASS)"
    } Catch { Write-Bad "WDigest could not be enabled" }

    Try {
        New-ADUser -Name $svc -SamAccountName $svc -UserPrincipalName "$svc@$Global:Domain" -Description "Backup automation service account - do not disable" -AccountPassword (ConvertTo-SecureString $pass -AsPlainText -Force) -PassThru | Enable-ADAccount
        Set-ADUser -Identity $svc -PasswordNeverExpires $true
        Add-ADGroupMember -Identity "Domain Admins" -Members $svc
        Write-Info "Cached-creds account: $svc / $pass (member of Domain Admins)"
    } Catch { Write-Bad "$svc could not be created: $($_.Exception.Message)" }

    # Scheduled task that actually logs on as the DA service account every 10 minutes.
    Try {
        $taskScript = "C:\Windows\System32\backup_report.cmd"
        Set-Content -Path $taskScript -Value "@echo off`r`necho %DATE% %TIME% backup report generated>>C:\Windows\Temp\backup_report.log" -Encoding ASCII
        $action  = New-ScheduledTaskAction -Execute $taskScript
        $trigger = New-ScheduledTaskTrigger -Once -At (Get-Date).Date.AddMinutes(5) -RepetitionInterval (New-TimeSpan -Minutes 10) -RepetitionDuration (New-TimeSpan -Days 3650)
        Register-ScheduledTask -TaskName "BackupReportJob" -Action $action -Trigger $trigger -User "$($Global:Domain.Split('.')[0])\$svc" -Password $pass -RunLevel Highest -Force | Out-Null
        Start-ScheduledTask -TaskName "BackupReportJob" -ErrorAction SilentlyContinue
        Write-Info "Scheduled task BackupReportJob runs as $svc every 10 min (password stored in LSA secrets)"
    } Catch { Write-Bad "BackupReportJob could not be registered: $($_.Exception.Message)" }
}

