    $List = @($List | Where-Object { $_ })
    if ($List.Count -eq 0) { return $null }
    return (VulnAD-GetRandom -InputList $List)
}

function VulnAD-NormalPool { return @($Global:Marketing + $Global:Sales + $Global:Accounting) }

function VulnAD-PickFreshUser {
    # Deterministically picks a user from $Pool that no other credential scenario has used yet,
    # so password/description plants never overwrite each other.
    param([array]$Pool)
    $avail = @($Pool | Where-Object { $_ -and ($Global:UsedUsers -notcontains $_) })
    if ($avail.Count -eq 0) { return $null }
    $u = VulnAD-GetRandom -InputList $avail
    $Global:UsedUsers += $u
    return $u
}

function VulnAD-LAPS {
    # Client/uye makine olmadigi icin "LDAP'tan local admin parolasi okuma"
    # senaryosunu sahte computer nesnelerine seed ederek kuruyoruz.
    # Windows LAPS semasi varsa onu dener, yoksa parolayi 'info' attribute'una yazar.
    Add-Type -AssemblyName System.Web
    $lowGroup = "IT Helpdesk"
    $decoys = @("WKSTN01","WKSTN02","SRV-FILE01","SRV-APP01","LAPTOP-CEO")
    $native = $false
    Try {
        Import-Module LAPS -ErrorAction Stop
        Update-LapsADSchema -Confirm:$false -ErrorAction Stop | Out-Null
        $native = $true
        Write-Info "Windows LAPS schema present (msLAPS-*). Password will still be seeded into a readable attribute."
    } Catch {
        Write-Info "Windows LAPS not present -> fallback: local admin password stored in the computer 'info' attribute"
    }
    Try { $grp = Get-ADGroup -Identity $lowGroup } Catch { $grp = $null }
    foreach ($c in $decoys) {
        $pw = "Adm!" + (VulnAD-GenPassword -len 10)
        Try { New-ADComputer -Name $c -SAMAccountName "$c`$" -Enabled $true -ErrorAction SilentlyContinue } Catch {}
        Try {
            Set-ADComputer -Identity $c -Replace @{ info = "ms-Mcs-AdmPwd (local admin): $pw" } -ErrorAction Stop
            $comp = Get-ADComputer -Identity $c
            if ($grp) { VulnAD-AddACL -Source $grp.sid -Destination $comp.DistinguishedName -Rights "GenericRead" }
            Write-Info "LAPS-style: local admin password seeded on $c ($lowGroup can read it)"
        } Catch { Write-Bad "LAPS decoy $c could not be set" }
    }
}

function VulnAD-UnconstrainedAndCoercion {
    # Client yok. Buradaki asil client'siz zincir:
    #   coerce (PetitPotam/PrinterBug) -> ADCS ESC8 (HTTP web enrollment) relay
    #   -> DC bilgisayar sertifikasi -> PKINIT/DCSync -> Domain Admin.
    # Print Spooler + EFSRPC yuzeyini acik birakiyoruz, ADCS zaten VulnAD-ADCS'de kurulu.

    Try {
        Set-Service -Name Spooler -StartupType Automatic -ErrorAction SilentlyContinue
        Start-Service -Name Spooler -ErrorAction SilentlyContinue
        Write-Info "Print Spooler enabled (MS-RPRN / PrinterBug coercion primitive)"
    } Catch { Write-Bad "Spooler could not be enabled" }

    # MS-EFSRPC (PetitPotam) DC'ye karsi calisir; ozel bir ayar gerekmez, sadece not.
    Write-Info "PetitPotam (MS-EFSRPC) target is the DC. Clientless path: coerce -> ADCS ESC8 relay -> DC cert -> DCSync"

    # Unconstrained Delegation isaretli sahte computer (BloodHound enum + teori).
    # NOT: TGT yakalamak icin normalde saldirganin delegation host'u gerekir;
    # bu obje enumeration icindir, client'siz asil cozum yukaridaki relay zinciridir.
    $unc = "SRV-LEGACY01"
    Try {
        New-ADComputer -Name $unc -SAMAccountName "$unc`$" -Enabled $true -ServicePrincipalNames "HOST/$unc.$Global:Domain","CIFS/$unc.$Global:Domain" -ErrorAction SilentlyContinue
        Set-ADAccountControl -Identity "$unc`$" -TrustedForDelegation $true -ErrorAction SilentlyContinue
        Write-Info "Unconstrained Delegation: $unc`$ (TRUSTED_FOR_DELEGATION) - enum/teori"
    } Catch { Write-Bad "Unconstrained delegation object could not be created" }
}

function VulnAD-ADCS-ESC6 {
    # CA politikasinda EDITF_ATTRIBUTESUBJECTALTNAME2 -> TUM template'lerde SAN suppliable.
    # Tek basina Domain Users bile herhangi bir enroll edilebilir template ile DA sertifikasi cikarir.
    Try {
        certutil -setreg policy\EditFlags +EDITF_ATTRIBUTESUBJECTALTNAME2 | Out-Null
        Restart-Service certsvc -ErrorAction SilentlyContinue
        Write-Info "ADCS ESC6: EDITF_ATTRIBUTESUBJECTALTNAME2 enabled (SAN can be specified on every template)"
    } Catch { Write-Bad "ESC6 flag could not be set (CA may not be installed)" }
}

function VulnAD-ADCS-ESC7 {
    # Dusuk yetkili gruba CA uzerinde ManageCA + Manage Certificates hakki (ESC7).
    # Grup, ESC7 -> (ESC6 benzeri) veya request onaylama ile DA sertifikasina gidebilir.
    Try {
        # Discover the CA's real registry key name instead of assuming "<domain>-CA"
        # (the actual name can differ, e.g. if AD CS was installed separately).
        $cfgRoot = "HKLM:\SYSTEM\CurrentControlSet\Services\CertSvc\Configuration"
        $caKey = Get-ChildItem -Path $cfgRoot -ErrorAction Stop | Where-Object { $_.PSChildName -ne 'EditFlags' } | Select-Object -First 1
        if (-not $caKey) { throw "no CA configuration key found under $cfgRoot (is the CA installed?)" }
        $regBase = $caKey.PSPath
        $sec = (Get-ItemProperty -Path $regBase -Name Security -ErrorAction Stop).Security
        $rsd = New-Object System.Security.AccessControl.RawSecurityDescriptor($sec, 0)
        $sddl = $rsd.GetSddlForm([System.Security.AccessControl.AccessControlSections]::All)

        $grpName = VulnAD-GetRandom -InputList $Global:NormalGroups
        $grp = Get-ADGroup -Identity $grpName
        $sid = $grp.SID.Value
        # ManageCA(0x1) + ManageCertificates(0x2) = 0x3
        $newAce = "(A;;0x3;;;$sid)"
        $sddl2 = $sddl -replace "(D:[A-Z]*)", "`$1$newAce"

        $rsd2 = New-Object System.Security.AccessControl.RawSecurityDescriptor($sddl2)
        $bytes = New-Object byte[] ($rsd2.BinaryLength)
        $rsd2.GetBinaryForm($bytes, 0)
        Set-ItemProperty -Path $regBase -Name Security -Value $bytes
        Restart-Service certsvc -ErrorAction SilentlyContinue
        Write-Info "ADCS ESC7: $grpName granted ManageCA+ManageCertificates over the CA"
    } Catch { Write-Bad "ESC7 could not be set: $($_.Exception.Message)" }
}

function VulnAD-GPOAbuse {
    # Dusuk/orta gruba, Domain Controllers OU'suna linkli bir GPO uzerinde edit hakki.
    # -> SharpGPOAbuse ile DC'ye immediate scheduled task push = SYSTEM on DC = DA.
    Try {
        Import-Module GroupPolicy -ErrorAction Stop
        $gpoName = "Workstation Hardening Policy"
        $gpo = $null
        Try { $gpo = Get-GPO -Name $gpoName -ErrorAction Stop } Catch { $gpo = New-GPO -Name $gpoName }
        $dcOU = "OU=Domain Controllers,$((Get-ADDomain).DistinguishedName)"
        Try { New-GPLink -Name $gpoName -Target $dcOU -ErrorAction SilentlyContinue | Out-Null } Catch {}
        $grp = VulnAD-GetRandom -InputList $Global:MidGroups
        Set-GPPermission -Name $gpoName -TargetName $grp -TargetType Group -PermissionLevel GpoEditDeleteModifySecurity -Replace -ErrorAction SilentlyContinue | Out-Null
        Write-Info "GPO Abuse: '$gpoName' linked to the DC OU, $grp can edit it (SharpGPOAbuse)"
    } Catch { Write-Bad "GPO abuse could not be set" }
}

function VulnAD-AdminSDHolder {
    # Dusuk yetkili kullaniciya AdminSDHolder uzerinde GenericAll.
    # SDProp (~60 dk) bu hakki TUM korumali gruplara (Domain Admins vb.) yayar => privesc + persistence.
    Try {
        $u = VulnAD-SafeRandomUser -List $Global:InitialAccessUsers
        if (-not $u) { $u = VulnAD-SafeRandomUser -List $Global:ITHelpdesk }
        if (-not $u) { $u = VulnAD-SafeRandomUser -List $Global:CreatedUsers }
        $uObj = Get-ADUser -Identity $u
        $dn = "CN=AdminSDHolder,CN=System,$((Get-ADDomain).DistinguishedName)"
        VulnAD-AddACL -Source $uObj.sid -Destination $dn -Rights "GenericAll"
        Write-Info "AdminSDHolder backdoor: $u GenericAll (SDProp propagates to protected groups)"
    } Catch { Write-Bad "AdminSDHolder ACL could not be granted" }
}

function VulnAD-PrivilegedGroups {
    # Dusuk kullanicilari Backup Operators / Server Operators'a koy.
    # Backup Operators -> DC'de SAM+SYSTEM hive backup -> secretsdump -> DA.
    # Server Operators -> DC servislerini manipule -> SYSTEM -> DA.
    Try {
        $u1 = VulnAD-PickFreshUser -Pool $Global:Marketing
        if (-not $u1) { $u1 = VulnAD-PickFreshUser -Pool $Global:Accounting }
        if ($u1) {
            Add-ADGroupMember -Identity "Backup Operators" -Members $u1 -ErrorAction SilentlyContinue
            Set-ADUser $u1 -Description "Nightly backup operator"
            Write-Info "Backup Operators: $u1 (DC SAM/registry backup -> DA)"
        }
        $u2 = VulnAD-PickFreshUser -Pool $Global:Sales
        if ($u2 -and $u2 -ne $u1) {
            Add-ADGroupMember -Identity "Server Operators" -Members $u2 -ErrorAction SilentlyContinue
            Write-Info "Server Operators: $u2 (DC services -> privesc)"
        }
    } Catch { Write-Bad "Privileged group membership could not be added" }
}

function VulnAD-GMSA {
    # Okunabilir gMSA: dusuk yetkili gruba PrincipalsAllowedToRetrieveManagedPassword.
    # -> ReadGMSAPassword (BloodHound edge), gMSA parolasi cekilip pass-the-hash.
    Try {
        # The KDS cmdlets live in the Kds module, which does not always auto-load. Import it first.
        Import-Module Kds -ErrorAction SilentlyContinue
        if (-not (Get-KdsRootKey -ErrorAction SilentlyContinue)) {
            Add-KdsRootKey -EffectiveTime ((Get-Date).AddHours(-10)) -ErrorAction Stop | Out-Null
            Write-Info "KDS root key created (back-dated, single-DC lab)"
        }
        $retrieveGroup = Get-ADGroup -Identity "IT Helpdesk"
        New-ADServiceAccount -Name "svc_gmsa01" -DNSHostName "svc_gmsa01.$Global:Domain" -PrincipalsAllowedToRetrieveManagedPassword $retrieveGroup -ErrorAction Stop
        Write-Info "gMSA: svc_gmsa01, the IT Helpdesk group can read its password (ReadGMSAPassword)"
    } Catch { Write-Bad "gMSA could not be created: $($_.Exception.Message)" }
}

function VulnAD-WeakUserFlags {
    # PASSWD_NOTREQD ve DONT_EXPIRE_PASSWORD gibi zayif hesap bayraklari (enum bulgulari).
    Try {
        $u1 = VulnAD-PickFreshUser -Pool $Global:Accounting
        if ($u1) { Set-ADUser -Identity $u1 -PasswordNotRequired $true; Write-Info "PASSWD_NOTREQD: $u1" }
        $u2 = VulnAD-PickFreshUser -Pool $Global:Sales
        if ($u2) { Set-ADUser -Identity $u2 -PasswordNeverExpires $true; Write-Info "DONT_EXPIRE_PASSWORD: $u2" }
    } Catch { Write-Bad "Weak user flags could not be set" }
}


function VulnAD-EternalBlue {
    # MS17-010 / EternalBlue.
    # ONEMLI GERCEK: MS17-010 YAMALANMIS bir sistemde script ile "acilamaz". Zafiyet SMBv1
    # surucusunun (srv.sys) yama-oncesi surumune baglidir ve 2016'da cumulative update
    # mantigi nedeniyle bu yama TEK BASINA geri alinamaz.
    # Bu fonksiyon: (1) SMBv1'i tam acar (onkosul), (2) DC gercekten vulnerable mi kontrol
    # edip net rapor verir. Gercekten acik olmasi icin 2016 RTM (build 14393.0) medyasindan
    # kurup ILK BOOT'tan itibaren update kapali olmasi gerekir (script update'i zaten kapatiyor).

    # 1) SMBv1 onkosulu (tam ac)
    Try {
        Enable-WindowsOptionalFeature -Online -FeatureName SMB1Protocol -All -NoRestart -ErrorAction SilentlyContinue | Out-Null
        Set-SmbServerConfiguration -EnableSMB1Protocol $true -Confirm:$false
        Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\LanmanServer\Parameters" -Name "SMB1" -Value 1 -Type DWord -Force
        New-NetFirewallRule -DisplayName "Allow SMB 445" -Direction Inbound -Protocol TCP -LocalPort 445 -Action Allow -ErrorAction SilentlyContinue | Out-Null
        Write-Info "SMBv1 fully enabled + listening on 445 (EternalBlue prerequisite)"
    } Catch { Write-Bad "SMBv1 could not be enabled" }

    # 2) Gercek vulnerability durumu raporu
    Try {
        $cv = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion"
        $build = [int]$cv.CurrentBuildNumber
        $ubr = try { [int]$cv.UBR } catch { -1 }
        $srv = (Get-Item "C:\Windows\System32\drivers\srv.sys" -ErrorAction SilentlyContinue).VersionInfo.FileVersion
        Write-Info "OS build: $build  UBR: $ubr  srv.sys: $srv"

        $vuln = $false
        if ($build -eq 14393 -and $ubr -ge 0 -and $ubr -lt 953) { $vuln = $true }  # 2016 pre-March2017
        elseif ($build -lt 14393) { $vuln = $true }                                 # daha eski OS'ler

        if ($vuln) {
            Write-Good "This DC is LIKELY VULNERABLE to MS17-010 (pre-patch build) - EternalBlue would work."
        } else {
            Write-Bad "This DC appears PATCHED against MS17-010 (build $build.$ubr)."
            Write-Bad "For an EternalBlue target: install from 2016 RTM 14393.0 media + keep update off from first boot,"
            Write-Bad "or use a separate unpatched target VM (Win7 SP1 / Server 2008R2 / 2012R2)."
        }
    } Catch { Write-Bad "MS17-010 status check could not be performed" }
}


function VulnAD-ConstrainedDelegation {
    # Klasik Constrained Delegation + Protocol Transition senaryosu.
    # Kill-chain: websvc$ hash ele gecir -> S4U2Self(Administrator) -> S4U2Proxy(CIFS/DC)
    # -> DC C$'a DA olarak erisim -> secretsdump / DCSync
    # Tek DC'de calisir: deleg hedefi DC'nin kendi servisleri.
    Add-Type -AssemblyName System.Web
    $svcName  = "websvc"
    $svcPass  = "Websvc@2024!"
    $dcFqdn   = (Get-ADDomainController).HostName

    # Servis hesabini olustur
    Try {
        New-ADUser -Name $svcName -SamAccountName $svcName -UserPrincipalName "$svcName@$Global:Domain" -ServicePrincipalNames "HTTP/$svcName.$Global:Domain" -AccountPassword (ConvertTo-SecureString $svcPass -AsPlainText -Force) -PassThru | Enable-ADAccount
        Add-ADGroupMember -Identity "IT Helpdesk" -Members $svcName -ErrorAction SilentlyContinue
    } Catch {}

    # msDS-AllowedToDelegateTo: CIFS + LDAP + HOST (CIFS -> DCSync icin sname swap)
    $spns = @("CIFS/$dcFqdn","LDAP/$dcFqdn","HOST/$dcFqdn")
    Try {
        Set-ADUser -Identity $svcName -Add @{"msDS-AllowedToDelegateTo" = $spns}
        # TRUSTED_TO_AUTH_FOR_DELEGATION = protocol transition (S4U2Self) acik
        Set-ADAccountControl -Identity $svcName -TrustedToAuthForDelegation $true
        Write-Info "Constrained Delegation: $svcName -> $spns (protocol transition ENABLED)"
        Write-Info "Kali: getST.py -spn CIFS/$dcFqdn -impersonate Administrator $Global:Domain/$svcName"
    } Catch { Write-Bad "Constrained delegation could not be set" }
}

function VulnAD-FootholdComputer {
    # Tahmın edilebilir bilgisayar hesabi: domaine katilmadan once elle olusturulmus,
    # parolasi hostname ile ayni bırakılmıs computer objesi.
    # Ogrenci: anon LDAP ile kesfeder, CME/netexec ile erisme dogrular,
    # machine account cred'iyle RBCD / ADCS (Certifried) / BloodHound enum yapar.
    $name = "WS-INTAKE"
    $pass = "ws-intake"          # tahmin edilebilir / zayif parola
    Try {
        New-ADComputer -Name $name -SAMAccountName "$name`$" -AccountPassword (ConvertTo-SecureString $pass -AsPlainText -Force) -Enabled $true -Description "Pre-staged workstation - pending domain join" -ErrorAction SilentlyContinue
        # Ogrencinin kesfetmesi icin description ile de isaretleyelim
        Write-Info "Foothold computer: $name`$ (password: $pass) - visible via anonymous LDAP"
        Write-Info "Kali: nxc smb <DC-IP> -u 'WS-INTAKE$' -p 'ws-intake' --shares"
    } Catch { Write-Bad "Foothold computer could not be created" }
}

function VulnAD-DSRMBackdoor {
    # DC'nin DSRM local admin hesabini normal calisirken agdan kullanilabilir yapar.
    # PERSISTENCE kill-chain:
    #   DA olduktan sonra:
    #   1) secretsdump.py 'domain/user:pass@<DC-IP>' -just-dc-user Administrator
    #      -> ciktidaki "SAM  Administrator" NTLM satiri = DSRM hash'i
    #   2) nxc smb <DC-IP> -u Administrator -H <NTLM> --local-auth
    #   -> DA parolasi degistirilse bile bu hash gecerli kalir (local SAM'de duruyor)
    #
    # NOT: DSRM parolasi DC kurulumunda belirlenmistir; script degistirmiyor.
    #      Ogrencinin gorevi: hash'i cikar ve DsrmAdminLogonBehavior=2 sayesinde kullan.
    Try {
        $regPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Lsa"
        Set-ItemProperty -Path $regPath -Name "DsrmAdminLogonBehavior" -Value 2 -Type DWord -Force
        Write-Info "DSRM backdoor: DsrmAdminLogonBehavior=2 enabled (network PtH possible)"
        Write-Info "DSRM kill-chain: [get DA] -> secretsdump SAM dump -> Administrator NTLM -> PtH --local-auth"
    } Catch { Write-Bad "DSRM registry could not be set" }
}


function VulnAD-Zerologon {
    # CVE-2020-1472 Zerologon - MS-NRPC AES-CFB8 IV sifir vektoru zafiyeti.
    # Gereksinim: Netlogon (her DC'de calisiyor) + RPC 135 + dinamik portlar erisimli.
    # Firewall zaten kapali (VulnAD-FirewallOff), ek ayar gerekmez.
    # Kill-chain: zerologon.py ile DC makine hesabini sifresiz authenticate et
    #             -> secretsdump ile domain hash'lerini al -> Golden Ticket veya DA pass reset

    Try {
        $nlSvc = Get-Service -Name "Netlogon" -ErrorAction Stop
        if ($nlSvc.Status -ne 'Running') { Start-Service Netlogon -ErrorAction SilentlyContinue }
        Write-Info "Netlogon service running (Zerologon prerequisite)"

        # RPC portlari (firewall kapali olsa da eksplisit rule ekle)
        New-NetFirewallRule -DisplayName "Allow RPC EpMap" -Direction Inbound -Protocol TCP -LocalPort 135 -Action Allow -ErrorAction SilentlyContinue | Out-Null
        New-NetFirewallRule -DisplayName "Allow RPC Dynamic" -Direction Inbound -Protocol TCP -LocalPort 49152-65535 -Action Allow -ErrorAction SilentlyContinue | Out-Null

        $cv    = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion"
        $build = [int]$cv.CurrentBuildNumber
        $ubr   = try { [int]$cv.UBR } catch { -1 }

        $vuln = ($build -eq 14393 -and $ubr -lt 3866) -or
                ($build -eq 17763 -and $ubr -lt 1397) -or
                ($build -lt 14393)

        if ($vuln) {
            Write-Good "CVE-2020-1472 Zerologon: DC appears VULNERABLE (build $build.$ubr < patched)"
            Write-Info "Kali: python3 zerologon.py <DC-NETBIOS> <DC-IP>   (impacket/dirkjanm)"
            Write-Info "      nxc smb <DC-IP> -u '' -p '' -M zerologon"
            Write-Info "      Sonrasi: secretsdump -no-pass -just-dc <domain>/<DC-NAME>\$@<DC-IP>"
        } else {
            Write-Bad "CVE-2020-1472: DC appears patched (build $build.$ubr)"
        }
    } Catch { Write-Bad "Zerologon check could not be performed: $($_.Exception.Message)" }
}

function VulnAD-Certifried {
    # CVE-2022-26923 Certifried - ADCS + MAQ > 0 ile domain user'dan DA'ya.
    # Tum onkosullar ZATEN MEVCUT: ADCS (VulnAD-ADCS) + MAQ=10 + WinRM/LDAP acik.
    # Ek kurulum GEREKMEZ. Bu fonksiyon onkosullari dogrular ve saldiri notunu loglar.
    #
    # Kill-chain:
    #   1) impacket-addcomputer -computer-name 'EVIL$' -computer-pass 'Evil1234!' domain/user:pass
    #   2) EVIL$'in dNSHostName'ini DC'nin FQDN'iyle esitle:
    #      Set-ADComputer EVIL -DnsHostName dc01.phantom.local  (ya da certipy ile)
    #   3) certipy req -u 'EVIL$' -p 'Evil1234!' -ca <CA-NAME> -template Machine
    #   4) certipy auth -pfx evil.pfx  -> DC'nin TGT'sini al (PKINIT)
    #   5) secretsdump / DCSync ile DA
    Try {
        $maq = (Get-ADObject (Get-ADDomain).DistinguishedName -Properties 'ms-DS-MachineAccountQuota').'ms-DS-MachineAccountQuota'
        $ca  = Get-ADObject -SearchBase "CN=Enrollment Services,CN=Public Key Services,CN=Services,$((Get-ADRootDSE).configurationNamingContext)" -Filter * -Properties dNSHostName -ErrorAction SilentlyContinue | Select-Object -First 1

        if ($maq -gt 0 -and $ca) {
            Write-Good "Certifried (CVE-2022-26923): READY (MAQ=$maq, CA=$($ca.Name))"
            Write-Info "Kill-chain: addcomputer -> dNSHostName=DC FQDN -> certipy req Machine -> PKINIT -> DCSync"
        } else {
            Write-Bad "Certifried: prerequisites incomplete (MAQ=$maq, CA found: $($null -ne $ca))"
        }
    } Catch { Write-Bad "Certifried check could not be performed: $($_.Exception.Message)" }
}

function VulnAD-PrintSummary {
    # Kurulum sonunda tum kritik bilgileri generate.log'a temiz bir blok olarak yazar.
    # Instructor bu dosyayi okuyarak direkt soru seti ve cevap anahtari olusturabilir.
    $sep = "=" * 72
    $out = @("", $sep, "  PHANTOM.LOCAL  -  LAB KURULUM OZETI  (INSTRUCTOR CHEAT SHEET)", $sep)

    # Domain
    Try {
        $dc   = Get-ADDomainController
        $out += ""
        $out += "[DOMAIN]"
        $out += "  Domain : $Global:Domain"
        $out += "  DC     : $($dc.HostName)"
        $out += "  DC IP  : $($dc.IPv4Address)"
    } Catch {}

    # Sabit kimlik bilgileri
    $out += ""
    $out += "[STATIC / GUESSABLE CREDENTIALS]"
    $out += "  Foothold Computer   WS-INTAKE`$           / ws-intake"
    $out += "  Constrained Deleg   websvc               / Websvc@2024!"
    $out += "  Autologon (reg)     svc_deploy           / Deploy2024!"
    $out += "  GPP cpassword       LocalAdmin           / LocalAdmin2024!   (SYSVOL)"
    $out += "  Decoy IT\Password   svc_backup           / B4ckup2023!"
    $out += "  Decoy IT\Password   old_admin            / Summer2022#"
    $out += "  Decoy IT\Password   temp_helpdesk        / Helpdesk!23"
    $out += "  Decoy Config JSON   app_svc              / AppS3rvice#2024"
    $out += "  DnsAdmins user      UberSecurePassword   (member name is in generate.log)"
    $out += "  DSRM                DC install password  (secretsdump SAM -> Administrator NTLM)"

    # AS-REP
    $out += ""
    $out += "[AS-REP ROASTING - DoesNotRequirePreAuth=True]"
    Try {
        $asrep = Get-ADUser -Filter {DoesNotRequirePreAuth -eq $true} -Properties DoesNotRequirePreAuth
        if ($asrep) { $asrep | ForEach-Object { $out += "  $($_.SamAccountName)" } }
        else { $out += "  (not found)" }
    } Catch { $out += "  (query failed)" }

    # Description'da parola
    $out += ""
    $out += "[PASSWORDS LEAKED IN DESCRIPTION FIELDS]"
    Try {
        Get-ADUser -Filter * -Properties Description |
            Where-Object { $_.Description -match "password|Pass|generated|parola" } |
            ForEach-Object { $out += "  $($_.SamAccountName.PadRight(25)) -> $($_.Description)" }
    } Catch { $out += "  (query failed)" }

    # SPN / Kerberoast
    $out += ""
    $out += "[KERBEROAST - SPN ACCOUNTS (RC4-only, weak password)]"
    Try {
        Get-ADUser -LDAPFilter "(&(servicePrincipalName=*)(!(sAMAccountName=krbtgt)))" -Properties ServicePrincipalName |
            ForEach-Object { $out += "  $($_.SamAccountName.PadRight(20)) SPN: $($_.ServicePrincipalName -join ' | ')" }
    } Catch { $out += "  (query failed)" }

    # Spray
    $out += ""
    $out += "[PASSWORD SPRAY - search for the 'Same Password' line in generate.log]"
    $out += "  Pattern: <domain_on_eki> + 3 haneli sayi  (ornek: phantom042)"

    # Constrained delegation
    $out += ""
    $out += "[CONSTRAINED DELEGATION (S4U2Self+Proxy)]"
    Try {
        Get-ADUser -Filter * -Properties "msDS-AllowedToDelegateTo","TrustedToAuthForDelegation" |
            Where-Object { $_."msDS-AllowedToDelegateTo" } |
            ForEach-Object {
                $pt = if ($_.TrustedToAuthForDelegation) {"ProtocolTransition=ACIK"} else {"ProtocolTransition=kapali"}
                $out += "  $($_.SamAccountName.PadRight(20)) -> $($_.'msDS-AllowedToDelegateTo' -join ', ')  [$pt]"
            }
    } Catch { $out += "  (query failed)" }

    # Privileged gruplar
    $out += ""
    $out += "[PRIVILEGED GROUP MEMBERSHIPS]"
    foreach ($g in @("Domain Admins","Backup Operators","Server Operators","DnsAdmins")) {
        Try {
            $mbr = Get-ADGroupMember -Identity $g -ErrorAction Stop | Select-Object -ExpandProperty SamAccountName
            if ($mbr) { $out += "  $($g.PadRight(22)): $($mbr -join ', ')" }
        } Catch {}
    }

    # ADCS
    $out += ""
    $out += "[ADCS VULNERABILITY MATRIX]"
    $out += "  ESC1  ESC1Template   : Domain Users enroll + SAN=saldirgan secimi"
    $out += "  ESC4  ESC1Template   : a NormalGroup has WriteDACL (can convert the template to ESC1)"
    $out += "  ESC6  CA flag        : EDITF_ATTRIBUTESUBJECTALTNAME2 on (all templates accept SAN)"
    $out += "  ESC7  CA ACL         : NormalGroup ManageCA+ManageCertificates"
    $out += "  ESC8  Web Enrollment : HTTP enabled + no LDAP signing -> NTLM relay target"
    $out += "  Certifried CVE-2022-26923: MAQ>0 + ADCS -> machine account dNSHostName spoof -> DC TGT"

    # Coercion / Relay
    $out += ""
    $out += "[COERCION + RELAY]"
    $out += "  Print Spooler ON     -> coerce the DC via PrinterBug (MS-RPRN)"
    $out += "  PetitPotam (EFSRPC)  -> ADCS ESC8 relay -> DC sertifikasi -> DCSync"
    $out += "  SMB Signing OFF      -> NTLM relay"
    $out += "  NTLMv1 ACTIVE        -> weak NTLM, captured hash -> hashcat"

    # Network CVE'ler
    $out += ""
    $out += "[NETWORK CVEs]"
    $out += "  CVE-2020-1472 Zerologon : Netlogon + RPC -> DC machine account passwordless auth -> DCSync"
    $out += "  CVE-2014-6287 HFS 2.3   : port 8080 -> rejetto_hfs_exec (msf) -> SYSTEM"
    $out += "  MS17-010 EternalBlue    : SMBv1 enabled, build-dependent (vuln check result in generate.log)"

    # Local privesc
    $out += ""
    $out += "[LOCAL PRIVESC VECTORS]"
    $out += "  Unquoted Service    VulnUpdateSvc  C:\Program Files\Vuln Update Service\ (herkes Modify)"
    $out += "  AlwaysInstallElevated HKLM+HKCU=1 -> malicious .msi installs as SYSTEM"
    $out += "  Writable Sched Task SystemMaintenanceCleanup -> C:\Users\Public\Maintenance\cleanup.bat"
    $out += "  Autologon Registry  svc_deploy / Deploy2024! -> Winlogon plaintext"
    $out += ""
    $out += "[CREDENTIALS IN MEMORY / LSA SECRETS]"
    $out += "  svc_backupadm / Backup#Adm2024!  (DOMAIN ADMIN)"
    $out += "    - Scheduled task 'BackupReportJob' runs as it every 10 min"
    $out += "    - Password stored in LSA secrets -> lsadump::secrets / secretsdump -sam -security"
    $out += "    - WDigest UseLogonCredential=1 -> sekurlsa::logonpasswords shows it in plaintext"
    $out += "    - Requires SYSTEM on the DC first (local privesc / WinRM / HFS)"

    # Persistence
    $out += ""
    $out += "[PERSISTENCE]"
    $out += "  DSRM Backdoor       DsrmAdminLogonBehavior=2 -> secretsdump SAM -> PtH --local-auth"
    $out += "  AdminSDHolder       GenericAll -> SDProp propagates to all protected groups (~60min)"
    $out += "  gMSA                svc_gmsa01, IT Helpdesk can read (ReadGMSAPassword)"
    $out += "  Ghost Admin         adminCount=1 but not in a privileged group"

    # Decoy / Enum
    $out += ""
    $out += "[ENUM / DECOY]"
    $out += "  Anonymous LDAP      enabled -> AD queries without authentication"
    $out += "  Public SMB Share    \\<DC>\Common -> Everyone FullControl, Guest enabled"
    $out += "  GPP cpassword       SYSVOL\...\Machine\Preferences\Groups\Groups.xml"
    $out += "  Decoy files         C:\Common\IT\Password_Backup.csv, Config\appsettings.json, Notes\admin_notes.txt"
    $out += "  LAPS-style          WKSTN01/02, SRV-FILE01, SRV-APP01, LAPTOP-CEO -> info attr'de local admin pw"
    $out += "  WinRM               enabled (5985) -> remote PS shell via Evil-WinRM"

    $out += ""
    $out += $sep
    $out += ""

    $out | ForEach-Object { Write-Info $_ }
    Write-Host ""
    Write-Host "`t[+] Full summary written to generate.log. Instructor cheat sheet ready." -ForegroundColor Cyan
}


function VulnAD-WriteDesktopReport {
    # Writes a WHAT / WHERE map of everything the lab created to the Desktop,
    # and copies the full verbose generate.log alongside it.
    $sep = ('=' * 78)
    $r = @()
    $r += $sep
    $r += "  PHANTOM AD - LAB BUILD REPORT (WHAT / WHERE)"
    $r += "  Domain : $Global:Domain    Date : $(Get-Date -Format 'yyyy-MM-dd HH:mm')    Seed : 1337"
    $r += $sep
    $r += ""

    # --- AD OBJECTS (live query) ---
    $r += "[AD OBJECTS]"
    Try { $r += "  Total users          : $((Get-ADUser -Filter * | Measure-Object).Count)   (location: AD -> Users)" } Catch { $r += "  Total users          : (query failed)" }
    foreach ($g in $Global:Groups) {
        Try {
            $m = @(Get-ADGroupMember -Identity $g -ErrorAction Stop)
            $r += ("  Group {0}: {1,2} members" -f $g.PadRight(20), $m.Count)
        } Catch {}
    }
    foreach ($pg in @("Domain Admins","DnsAdmins","Backup Operators","Server Operators")) {
        Try {
            $mm = (Get-ADGroupMember -Identity $pg -ErrorAction Stop | Select-Object -ExpandProperty SamAccountName) -join ', '
            if ($mm) { $r += "  $($pg.PadRight(20)): $mm" }
        } Catch {}
    }
    Try {
        $spn = Get-ADUser -LDAPFilter "(&(servicePrincipalName=*)(!(sAMAccountName=krbtgt)))" -Properties ServicePrincipalName | Select-Object -ExpandProperty SamAccountName
        if ($spn) { $r += "  SPN / Kerberoast     : $($spn -join ', ')" }
    } Catch {}
    $r += ""

    # --- FILE SYSTEM ARTIFACTS ---
    $r += "[FILE SYSTEM - WHAT / WHERE]"
    $r += "  Public SMB share       \\$env:COMPUTERNAME\Common   (Everyone FullControl, Guest, null session)"
    $r += "  Decoy documents        C:\Common\Contracts, \IT, \Notes, \HR, \Finance, \Config"
    $r += "  DnsAdmins breadcrumb   C:\Common\DNSrestart.ps1"
    $r += "  HFS 2.3 (CVE-2014-6287) C:\HFS\hfs.exe"
    $r += "  Unquoted service dir   C:\Program Files\Vuln Update Service\   (Authenticated Users: Modify)"
    $r += "  Writable sched task    C:\Users\Public\Maintenance\cleanup.bat   (runs as SYSTEM)"
    $r += "  GPP cpassword          \\$Global:Domain\SYSVOL\...\Machine\Preferences\Groups\Groups.xml"
    $r += ""

    # --- REGISTRY CHANGES ---
    $r += "[REGISTRY - WHAT / WHERE]"
    $r += "  AlwaysInstallElevated  HKLM & HKCU\SOFTWARE\Policies\Microsoft\Windows\Installer = 1"
    $r += "  Autologon plaintext    HKLM\...\Winlogon   (svc_deploy / Deploy2024!)"
    $r += "  NTLMv1 (LmCompat=1)    HKLM\SYSTEM\CurrentControlSet\Control\Lsa\LmCompatibilityLevel = 1"
    $r += "  LDAP channel binding   HKLM\...\NTDS\Parameters\LdapEnforceChannelBinding = 0"
    $r += "  DSRM backdoor          HKLM\...\Control\Lsa\DsrmAdminLogonBehavior = 2"
    $r += "  Windows Update off     HKLM\...\WindowsUpdate\AU\NoAutoUpdate = 1"
    $r += "  Defender off           HKLM\...\Windows Defender\DisableAntiSpyware = 1"
    $r += ""

    # --- SERVICE / PROTOCOL / TASK ---
    $r += "[SERVICE / PROTOCOL / TASK]"
    $r += "  SMBv1                  ENABLED  (EternalBlue surface)"
    $r += "  SMB signing            DISABLED (NTLM relay)"
    $r += "  WinRM                  ENABLED  (5985 -> Evil-WinRM)"
    $r += "  Anonymous LDAP         ENABLED"
    $r += "  Scheduled task (SYSTEM) SystemMaintenanceCleanup"
    $r += "  Windows Update svc     wuauserv / UsoSvc / WaaSMedicSvc / bits -> Disabled"
    $r += ""
    $r += $sep
    $r += "  Full verbose log: generate.log in this same folder (C:\VulnAD-Build)"
    $r += $sep

    # Write the report ONLY to the Administrators-only build folder (never the Public desktop,
    # which every student could read). Delete C:\VulnAD-Build before exporting the VM.
    Try {
        $reportPath = Join-Path $Global:LogDir "VulnAD_Lab_Report.txt"
        $r | Out-File -FilePath $reportPath -Encoding utf8 -Force
        Write-Info "Lab report written: $reportPath"
    } Catch { Write-Bad "Report could not be written" }
}

function Invoke-VulnAD {
    Param(
        [int]$UsersLimit = 50,
        [Parameter(Mandatory=$True,ValueFromPipeline=$True,ValueFromPipelineByPropertyName=$True,Position=1)]
        [ValidateNotNullOrEmpty()]
        [System.String]
        $DomainName
    )
    # --- DETERMINISTIC BUILD: fixed seed. Every install comes out identical. ---
    # Change this number for a different lab variant (e.g. one seed per class).
    VulnAD-SeedRandom -Seed 1337

    # Administrators-only build folder for the log + cheat sheet. Created BEFORE any Write-Info.
    Try {
        New-Item -ItemType Directory -Path $Global:LogDir -Force | Out-Null
        icacls "$Global:LogDir" /inheritance:r /grant:r "*S-1-5-32-544:(OI)(CI)F" /grant:r "*S-1-5-18:(OI)(CI)F" | Out-Null
        Set-Content -Path $Global:LogFile -Value "" -Encoding UTF8
    } Catch {}

    ShowBanner
    $Global:Domain = $DomainName
    VulnAD-SystemTweaks
    Write-Good "System Tweaks (Defender/Update/Power) Done"
    # LockoutThreshold 0 = accounts NEVER lock out. Deliberate for an exam: a student cannot
    # brick the AS-REP / spray accounts and get stuck. For a realistic corporate policy set it to 5
    # (then warn students to spray one attempt per account per observation window).
    Set-ADDefaultDomainPasswordPolicy -Identity $Global:Domain -LockoutThreshold 0 -LockoutDuration 00:01:00 -LockoutObservationWindow 00:01:00 -ComplexityEnabled $false -ReversibleEncryptionEnabled $False -MinPasswordLength 4
    Try { Set-ADDomain -Identity $Global:Domain -Replace @{"ms-DS-MachineAccountQuota"=10} } Catch {}
    if ($UsersLimit -lt 30) {
        Write-Output "Setting minimum 30 users"
        $UsersLimit = 30
    }
    VulnAD-AddADUser -limit $UsersLimit
    Write-Good "Users Created"
    VulnAD-AddADGroup -GroupList $Global:HighGroups
    Write-Good "$Global:HighGroups Groups Created"
    VulnAD-AddADGroup -GroupList $Global:MidGroups
    Write-Good "$Global:MidGroups Groups Created"
    VulnAD-AddADGroup -GroupList $Global:NormalGroups
    Write-Good "$Global:NormalGroups Groups Created"
    VulnAD-Acls
    Write-Good "ACL Done"
    VulnAD-Kerberoasting
    Write-Good "Kerberoasting Done"
    VulnAD-ASREPRoasting
    Write-Good "AS-REPRoasting Done"
    VulnAD-DnsAdmins
    Write-Good "DnsAdmins Done"
    VulnAD-DefaultPassword
    Write-Good "Leaked Password Done"
    VulnAD-PasswordSpraying
    Write-Good "Password Spraying Done"
    VulnAD-BadAcls
    Write-Good "Bad ACL Done"
    Write-Good "DCSync Done"
    VulnAD-RBCD
    Write-Good "RBCD Done"
    VulnAD-ADCS
    Write-Good "AD CS (ESC1/ESC4) Done"
    VulnAD-Certifried
    Write-Good "Certifried/CVE-2022-26923 (prereq check + doc) Done"
    VulnAD-ShadowCredentials
    Write-Good "Shadow Credentials Done"
    VulnAD-VulnerableServices
    Write-Good "HFS Vulnerable Service Done"
    VulnAD-LocalPrivesc
    Write-Good "Local Privesc Vectors (Unquoted Path / AlwaysInstallElevated / Sched Task / Autologon) Done"
    VulnAD-DisableSMBSigning
    Write-Good "SMB Signing Disabled"
    VulnAD-EnableWinRM
    Write-Good "Windows Remote Management Enabled"
    VulnAD-AnonymousLDAP
    Write-Good "Anonymous LDAP Query Enabled"
    VulnAD-PublicSMBShare
    Write-Good "Created Public SMB Share"
    VulnAD-DecoyFiles
    Write-Good "Decoy Files Created"
    VulnAD-DepartmentShares
    Write-Good "Department Shares (Finance/HR/Sales/IT/Backups) Created"
    VulnAD-EnumExtras
    Write-Good "Enumeration Extras (GPP cpassword / descriptions / ghost admin) Done"
    VulnAD-ProtocolWeaknesses
    Write-Good "Protocol Weaknesses (NTLM/SMBv1/LDAP) Done"
    VulnAD-EternalBlue
    Write-Good "EternalBlue/MS17-010 (prereqs + vuln check) Done"
    VulnAD-Zerologon
    Write-Good "Zerologon/CVE-2020-1472 (prereqs + vuln check) Done"
    VulnAD-ConstrainedDelegation
    Write-Good "Constrained Delegation (websvc / S4U2Self+Proxy) Done"
    VulnAD-FootholdComputer
    Write-Good "Foothold Computer (WS-INTAKE / guessable password) Done"
    VulnAD-DSRMBackdoor
    Write-Good "DSRM Backdoor (persistence) Done"
    VulnAD-LAPS
    Write-Good "LAPS (Local Admin Password) Done"
    VulnAD-UnconstrainedAndCoercion
    Write-Good "Unconstrained Delegation + Spooler/PetitPotam Surface Done"
    VulnAD-ADCS-ESC6
    Write-Good "AD CS ESC6 (EDITF_ATTRIBUTESUBJECTALTNAME2) Done"
    VulnAD-ADCS-ESC7
    Write-Good "AD CS ESC7 (ManageCA/ManageCertificates) Done"
    VulnAD-GPOAbuse
    Write-Good "GPO ACL Abuse (DC OU) Done"
    VulnAD-AdminSDHolder
    Write-Good "AdminSDHolder Backdoor Done"
    VulnAD-PrivilegedGroups
    Write-Good "Backup/Server Operators Done"
    VulnAD-GMSA
    Write-Good "gMSA ReadPassword Done"
    VulnAD-WeakUserFlags
    Write-Good "Weak User Flags (NOTREQD / NEVEREXPIRE) Done"
    VulnAD-CachedAdminCreds
    Write-Good "Cached DA Credentials (WDigest + scheduled task as svc_backupadm) Done"
    VulnAD-FirewallOff
    Write-Good "Firewall Turned Off"
    VulnAD-PrintSummary
    Write-Good "Instructor cheat sheet -> $Global:LogFile"
    VulnAD-WriteDesktopReport
    Write-Good "Lab report -> $Global:LogDir\VulnAD_Lab_Report.txt"

    Write-Host ""
    Write-Host "`t[!] BEFORE EXPORTING THE VM:" -ForegroundColor Yellow
    Write-Host "`t    1. Copy C:\VulnAD-Build somewhere safe (it holds every password + the cheat sheet)." -ForegroundColor Yellow
    Write-Host "`t    2. DELETE C:\VulnAD-Build so students cannot read it." -ForegroundColor Yellow
    Write-Host "`t    3. Make sure a vulnerable C:\HFS\hfs.exe (build < 2.3c) is in place for CVE-2014-6287." -ForegroundColor Yellow
    Write-Host "`t    4. Take a VM snapshot (Zerologon breaks the DC account when a student runs it)." -ForegroundColor Yellow
    Write-Host ""
    Write-Output "Restarting in 30 seconds..."
    Start-Sleep -Seconds 30
    Restart-Computer -Force
}

